/**
 * Fitness plans (§3) — the week the app builds for you.
 *
 * The plan is generated by rule, not by a model (`buildWeek` in @pulse/shared,
 * and see that file's header for why). This router's job is to decide *when* to
 * generate, and then to never lose what the user did with it.
 *
 * The rule that shapes everything here: **a generated row is the user's the
 * moment they touch it.** Regenerating a week must not wipe a session they
 * ticked off or rated, so generation only ever fills days that do not exist
 * yet. A day the user has started belongs to them, and a plan that quietly
 * rewrote it would be the same class of lie as an empty state over a failed
 * request.
 *
 * userId always comes from ctx.user. No health values are logged.
 */
import { TRPCError } from "@trpc/server";
import {
  addDays,
  buildWeek,
  completeSessionInput,
  fitnessWeekInput,
  focusForMetric,
  toggleExerciseInput,
  weekStartOf,
  type PlannedExercise,
  type PlannedSession,
  type SessionFeedback,
} from "@pulse/shared";
import { router, ownerProcedure } from "../trpc";
import { prisma } from "../db";
import { toDbDate, fromDbDate } from "../dbDate";

const userProcedure = ownerProcedure;

/** A stored row, in the shape the client renders. */
type SessionView = PlannedSession & {
  completed: boolean;
  feedback: SessionFeedback | null;
};

type Row = {
  date: Date;
  title: string;
  items: unknown;
  intensity: number;
  rationale: string;
  rest: boolean;
  completedAt: Date | null;
  feedback: SessionFeedback | null;
};

/**
 * Items come back from Json as `unknown`. Validate rather than cast: a row
 * written by an older version of the planner must not crash the screen.
 */
function readItems(raw: unknown): PlannedExercise[] {
  if (!Array.isArray(raw)) return [];
  return raw.flatMap((v): PlannedExercise[] => {
    if (typeof v !== "object" || v === null) return [];
    const o = v as Record<string, unknown>;
    if (typeof o.slug !== "string" || typeof o.name !== "string") return [];
    return [
      {
        slug: o.slug,
        name: o.name,
        sets: typeof o.sets === "number" ? o.sets : 1,
        reps: typeof o.reps === "number" ? o.reps : 1,
        hold: o.hold === true,
        target: typeof o.target === "string" ? o.target : "",
        done: o.done === true,
      },
    ];
  });
}

function present(r: Row): SessionView {
  return {
    date: fromDbDate(r.date),
    title: r.title,
    items: readItems(r.items),
    intensity: r.intensity,
    rationale: r.rationale,
    rest: r.rest,
    completed: r.completedAt !== null,
    feedback: r.feedback,
  };
}

const SELECT = {
  date: true,
  title: true,
  items: true,
  intensity: true,
  rationale: true,
  rest: true,
  completedAt: true,
  feedback: true,
} as const;

/** Today's readiness, if a snapshot exists. Null is a real answer. */
async function readinessFor(userId: string, date: string): Promise<number | null> {
  const snap = await prisma.readinessSnapshot.findUnique({
    where: { userId_date: { userId, date: toDbDate(date) } },
    select: { score: true },
  });
  return snap?.score ?? null;
}

/** A stable per-user number, so the same week always builds the same plan. */
function seedFor(userId: string, weekStart: string): number {
  let h = 0;
  for (const ch of `${userId}:${weekStart}`) h = (h * 31 + ch.charCodeAt(0)) % 100003;
  return h;
}

export const fitnessRouter = router({
  /**
   * The week containing `date`, generating any day that does not exist yet.
   *
   * Returns `planned: false` when the user has no goal. The brief's empty state
   * is "Set a goal and I'll build your week" — so we do not build one, rather
   * than inventing a default and pretending it was chosen for them.
   */
  week: userProcedure.input(fitnessWeekInput).query(async ({ ctx, input }) => {
    const userId = ctx.user.id;
    const weekStart = weekStartOf(input.date);

    const [goal, existing, readiness] = await Promise.all([
      prisma.goal.findFirst({
        where: { userId },
        orderBy: { createdAt: "desc" },
        select: { description: true, targetMetric: true },
      }),
      prisma.fitnessSession.findMany({
        where: { userId, date: { gte: toDbDate(weekStart), lte: toDbDate(addDays(weekStart, 6)) } },
        orderBy: { date: "asc" },
        select: SELECT,
      }),
      readinessFor(userId, input.date),
    ]);

    if (!goal) {
      return { planned: false as const, goal: null, sessions: [] as SessionView[] };
    }

    const have = new Set(existing.map((r) => fromDbDate(r.date)));
    if (have.size < 7) {
      // The most recent rating the user gave, so a fresh week starts from what
      // they last told us rather than from nothing.
      const last = await prisma.fitnessSession.findFirst({
        where: { userId, feedback: { not: null } },
        orderBy: { date: "desc" },
        select: { feedback: true },
      });

      const planned = buildWeek({
        weekStart,
        focus: focusForMetric(goal.targetMetric),
        readiness,
        lastFeedback: last?.feedback ?? null,
        seed: seedFor(userId, weekStart),
      });

      // Only the days that are missing. A day the user has already touched is
      // theirs — createMany with skipDuplicates makes that a property of the
      // write rather than a race we hope not to lose.
      await prisma.fitnessSession.createMany({
        data: planned
          .filter((p) => !have.has(p.date))
          .map((p) => ({
            userId,
            date: toDbDate(p.date),
            title: p.title,
            items: p.items,
            intensity: p.intensity,
            readiness,
            rationale: p.rationale,
            rest: p.rest,
          })),
        skipDuplicates: true,
      });

      const rows = await prisma.fitnessSession.findMany({
        where: { userId, date: { gte: toDbDate(weekStart), lte: toDbDate(addDays(weekStart, 6)) } },
        orderBy: { date: "asc" },
        select: SELECT,
      });
      return { planned: true as const, goal: goal.description, sessions: rows.map(present) };
    }

    return { planned: true as const, goal: goal.description, sessions: existing.map(present) };
  }),

  /** Tick one exercise off, or back on. Scoped to the caller's own session. */
  toggleExercise: userProcedure.input(toggleExerciseInput).mutation(async ({ ctx, input }) => {
    const row = await prisma.fitnessSession.findUnique({
      where: { userId_date: { userId: ctx.user.id, date: toDbDate(input.date) } },
      select: { id: true, items: true },
    });
    if (!row) throw new TRPCError({ code: "NOT_FOUND" });

    const items = readItems(row.items);
    if (!items.some((i) => i.slug === input.slug)) {
      throw new TRPCError({ code: "NOT_FOUND", message: "That exercise isn't in this session." });
    }
    const next = items.map((i) => (i.slug === input.slug ? { ...i, done: input.done } : i));

    await prisma.fitnessSession.update({ where: { id: row.id }, data: { items: next } });
    return { items: next };
  }),

  /**
   * Finish a session and say how it felt.
   *
   * The rating is not applied to this week — it shapes the NEXT one, through
   * `feedbackAdjustment`. Rewriting the week someone is halfway through would
   * move the goalposts under them.
   */
  complete: userProcedure.input(completeSessionInput).mutation(async ({ ctx, input }) => {
    const { count } = await prisma.fitnessSession.updateMany({
      where: { userId: ctx.user.id, date: toDbDate(input.date) },
      data: { completedAt: new Date(), feedback: input.feedback },
    });
    if (count === 0) throw new TRPCError({ code: "NOT_FOUND" });
    return { ok: true as const };
  }),

  /**
   * Throw away the untouched days of this week and rebuild them against
   * today's readiness.
   *
   * Deliberately narrow: a session that has been started or rated is kept. The
   * user asked for a new plan, not for their record of what they actually did
   * to be deleted.
   */
  regenerate: userProcedure.input(fitnessWeekInput).mutation(async ({ ctx, input }) => {
    const userId = ctx.user.id;
    const weekStart = weekStartOf(input.date);
    const range = { gte: toDbDate(weekStart), lte: toDbDate(addDays(weekStart, 6)) };

    const untouched = await prisma.fitnessSession.findMany({
      where: {
        userId,
        date: range,
        completedAt: null,
        feedback: null,
      },
      select: { id: true, items: true },
    });

    // "Untouched" means nothing ticked, too — a half-done session is a record.
    const removable = untouched
      .filter((r) => !readItems(r.items).some((i) => i.done))
      .map((r) => r.id);

    if (removable.length > 0) {
      await prisma.fitnessSession.deleteMany({ where: { id: { in: removable } } });
    }
    return { rebuilt: removable.length };
  }),
});

